/* ?GREET(MSG(label)) -- print a string via UART_PUTS */
MACRODEF GREET;
    REQUIRED MSG(lvalue);
    GEN DO;
        'la      r0,{MSG}';
        'push    r0';
        'la      r2,_UART_PUTS';
        'jal     r1,(r2)';
        'add     sp,3';
    END;
END;
