    /* Re-walk with a clearer structure */
    PREV = 0;
    CURR = _PLSW_FREE_HEAD;
    DO WHILE (CURR != 0);
        IF (CURR >= BLOCK) THEN DO;
            /* CURR is first free block at or above BLOCK; stop. */
            CURR = CURR;  /* no-op; the IF guards exit via flag below */
        END;
        IF (CURR != 0) THEN DO;
            IF (CURR < BLOCK) THEN DO;
                PREV = CURR;
                _PLSW_BP = CURR;
                CURR = _PLSW_BP->_PLSW_BLOCK_NEXT;
            END;
            ELSE
                CURR_NEXT = 0;  /* break-equivalent */
        END;
    END;

    /* Link block in: block.next = curr; prev.next = block (or head) */
    _PLSW_BP = BLOCK;
    _PLSW_BP->_PLSW_BLOCK_NEXT = CURR;
    IF (PREV = 0) THEN
        _PLSW_FREE_HEAD = BLOCK;
    ELSE DO;
        _PLSW_BP = PREV;
        _PLSW_BP->_PLSW_BLOCK_NEXT = BLOCK;
    END;

    /* Forward coalesce: if BLOCK end touches CURR, merge them */
    _PLSW_BP = BLOCK;
    BLK_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
    IF (CURR != 0) THEN DO;
        IF (BLOCK + BLK_SIZE = CURR) THEN DO;
            _PLSW_BP = CURR;
            NEXT_AFTER = _PLSW_BP->_PLSW_BLOCK_NEXT;
            BLK_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
            _PLSW_BP = BLOCK;
            _PLSW_BP->_PLSW_BLOCK_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE + BLK_SIZE;
            _PLSW_BP->_PLSW_BLOCK_NEXT = NEXT_AFTER;
        END;
    END;

    RETURN(0);
END;

%ENDIF;

