423	/* Resolve ADDR(var) to assembly label _var for GEN substitution.
424	 * Argument text arrives as "ADDR ( VARNAME )" (tokens with spaces).
425	 * Returns 1 if resolved (appends _VARNAME to expansion buffer), 0 if not ADDR. */
426	int mac_resolve_addr(char *val) {
427	    int i = 0;
428	    int ni;
429	    char name[MACRO_NAME_MAX];
