431	    /* Skip leading whitespace */
432	    while (val[i] == 32) i = i + 1;
433	
434	    /* Check for ADDR (case-insensitive) */
435	    if ((val[i] == 'A' || val[i] == 'a') &&
436	        (val[i+1] == 'D' || val[i+1] == 'd') &&
437	        (val[i+2] == 'D' || val[i+2] == 'd') &&
438	        (val[i+3] == 'R' || val[i+3] == 'r') &&
439	        !is_alnum(val[i+4])) {
