            char word[MACRO_NAME_MAX];
            int wi = 0;
            while (i < blen && is_alnum(body[i]) && wi < MACRO_NAME_MAX - 1) {
                word[wi] = body[i];
                wi = wi + 1;
                i = i + 1;

