%INCLUDE _plsw_storage;

DCL A INT;
DCL B INT;
DCL C INT;
DCL BIG INT;
DCL RC INT;

MAIN: PROC;
    ?GETMAIN(LENGTH(100), ADDRESS(A), RC(RC));
    ?GETMAIN(LENGTH(100), ADDRESS(B), RC(RC));
    ?GETMAIN(LENGTH(100), ADDRESS(C), RC(RC));

    IF (A != 0 AND B != 0 AND C != 0) THEN
        CALL UART_PUTS(ADDR(MSG_3OK));
    ELSE
        CALL UART_PUTS(ADDR(MSG_3FAIL));

    /* Free in reverse so each forward-coalesce extends the gap */
    ?FREEMAIN(LENGTH(100), ADDRESS(C), RC(RC));
    ?FREEMAIN(LENGTH(100), ADDRESS(B), RC(RC));
    ?FREEMAIN(LENGTH(100), ADDRESS(A), RC(RC));

