 * macro name. After this function returns, cur_type points at
 * the token immediately following the last clause's closing ')'
 * -- typically TOK_SEMI, but the caller is responsible for
 * consuming the statement terminator.
 *
 * Returns macro index or -1 on error. */
int mac_parse_invoke(void) {
    mac_expand_err = 0;
    mac_expand_errmsg[0] = 0;

    /* cur_type should be TOK_QUESTION; advance to the macro name */
    lex_scan();

    if (cur_type != TOK_IDENT) {
        mac_exp_error("expected macro name after ?");
        return -1;
    }

    int mi = mac_lookup(cur_text);
    if (mi < 0) {
        mac_exp_error("unknown macro");
        return -1;
    }

    /* Clear argument values */
    int ai = 0;
    while (ai < MAC_ARG_MAX) {
        mac_arg_set[ai] = 0;
        mac_arg_val(ai)[0] = 0;
        ai = ai + 1;
    }

    lex_scan(); /* first keyword (or end-of-invocation token) */

    /* Parse keyword clauses. The invocation ends when we see a
     * token that isn't a clause-introducing TOK_IDENT -- typically
     * TOK_SEMI, but any statement-boundary token works. */
    while (cur_type == TOK_IDENT && !mac_expand_err) {

        /* Find matching clause */
        char kw[MACRO_NAME_MAX];
        str_ncopy(kw, cur_text, MACRO_NAME_MAX);
        int ci = 0;
        int found = -1;
        while (ci < mac_cl_count[mi]) {
            if (str_eq_nocase(kw, mac_cl_name(mi, ci))) {
                found = ci;
                break;
            }
            ci = ci + 1;
        }

        if (found < 0) {
            mac_exp_error("unknown keyword in macro invocation");
            return -1;
        }

        lex_scan(); /* expect '(' */
        if (cur_type != TOK_LPAREN) {
            mac_exp_error("expected ( after keyword");
            return -1;
        }

        /* Collect value tokens until matching ')' */
        lex_scan();
        char *val = mac_arg_val(found);
        int vpos = 0;
        int depth = 0;

        while (cur_type != TOK_EOF && !mac_expand_err) {
            if (cur_type == TOK_LPAREN) {
                depth = depth + 1;
            }
            if (cur_type == TOK_RPAREN) {
                if (depth == 0) break;
                depth = depth - 1;
            }

            /* Append token text to value */
            int tlen = str_len(cur_text);
            if (vpos > 0 && vpos < MAC_ARG_VAL_MAX - 2) {
                val[vpos] = 32; /* space between tokens */
                vpos = vpos + 1;
            }
            if (vpos + tlen < MAC_ARG_VAL_MAX - 1) {
                str_copy(val + vpos, cur_text);
                vpos = vpos + tlen;
            }
            lex_scan();
        }
        val[vpos] = 0;
        mac_arg_set[found] = 1;

        lex_scan(); /* skip ')' of the clause; advance to next clause or terminator */
    }

    /* Check required clauses */
    ci = 0;
    while (ci < mac_cl_count[mi]) {
        int idx = mac_cl_idx(mi, ci);
        if (mac_cl_req[idx] == MCLAUSE_REQUIRED && !mac_arg_set[ci]) {
            mac_exp_error("missing required keyword");
            return -1;
        }
        ci = ci + 1;
    }

    return mi;
}

