    DCL BLOCK INT;
    DCL EXPECTED INT;
    DCL PREV INT;
    DCL CURR INT;
    DCL BLK_SIZE INT;
    DCL NEXT_AFTER INT;
    DCL NEXT_SIZE INT;

    BLOCK = USERADDR - 6;
    EXPECTED = LEN + 6;

    _PLSW_BP = BLOCK;
    /* Double-free / invalid-pointer check */
    IF (_PLSW_BP->_PLSW_BLOCK_NEXT != _PLSW_ALLOC_MAGIC) THEN
        RETURN(1);
    /* Size mismatch */
    IF (_PLSW_BP->_PLSW_BLOCK_SIZE != EXPECTED) THEN
        RETURN(2);

    /* Sorted insert: walk free list to find PREV (last block with
     * addr < BLOCK) and CURR (first block with addr >= BLOCK). */
    PREV = 0;
    CURR = _PLSW_FREE_HEAD;
    DO WHILE (CURR != 0 AND CURR < BLOCK);
        PREV = CURR;
        _PLSW_BP = CURR;
        CURR = _PLSW_BP->_PLSW_BLOCK_NEXT;
    END;

    /* Link block in: block.next = curr; prev.next = block (or head) */
    _PLSW_BP = BLOCK;
    _PLSW_BP->_PLSW_BLOCK_NEXT = CURR;
    IF (PREV = 0) THEN
        _PLSW_FREE_HEAD = BLOCK;
    ELSE DO;
        _PLSW_BP = PREV;
        _PLSW_BP->_PLSW_BLOCK_NEXT = BLOCK;
    END;

    /* Forward coalesce: if BLOCK end touches CURR, merge */
    _PLSW_BP = BLOCK;
    BLK_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
    IF (CURR != 0) THEN DO;
        IF (BLOCK + BLK_SIZE = CURR) THEN DO;
            _PLSW_BP = CURR;
            NEXT_AFTER = _PLSW_BP->_PLSW_BLOCK_NEXT;
            NEXT_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
            _PLSW_BP = BLOCK;
            _PLSW_BP->_PLSW_BLOCK_SIZE = BLK_SIZE + NEXT_SIZE;
            _PLSW_BP->_PLSW_BLOCK_NEXT = NEXT_AFTER;
        END;
    END;

    RETURN(0);
END;

%ENDIF;

/* --- PL/X-style macros wrapping the procedures ---
 *
 * Defined unconditionally (outside the PLSW_STORAGE_HEADERS_ONLY
 * guard) so non-entry modules can use the macros even when their
 * include doesn't emit the impl + heap. The macro expansions
 * call the procedures, which the linker resolves to the entry
 * module's definitions. */

MACRODEF GETMAIN;
    REQUIRED LENGTH(expr);
    REQUIRED ADDRESS(lvalue);
    REQUIRED RC(lvalue);
    {ADDRESS} = _PLSW_GETMAIN({LENGTH});
    IF ({ADDRESS} = 0) THEN {RC} = 4;
    ELSE {RC} = 0;
END;

MACRODEF FREEMAIN;
    REQUIRED LENGTH(expr);
    REQUIRED ADDRESS(lvalue);
    REQUIRED RC(lvalue);
    {RC} = _PLSW_FREEMAIN({ADDRESS}, {LENGTH});
END;

