1	/* _plsw_storage.msw -- PL/SW heap allocator runtime
2	 *
3	 * Provides _PLSW_GETMAIN / _PLSW_FREEMAIN procedures backed by
4	 * a free-list allocator over a statically-declared heap region,
5	 * plus PL/I-flavored ?GETMAIN / ?FREEMAIN macros that wrap them.
6	 *
7	 *   %INCLUDE _plsw_storage;       -- entry module: impl + heap
8	 *
9	 *   %DEFINE PLSW_STORAGE_HEADERS_ONLY 1;
10	 *   %INCLUDE _plsw_storage;       -- non-entry module: header only
11	 *
12	 *   %DEFINE PLSW_HEAP_SIZE 32768; -- override default 64KB heap
13	 *   %INCLUDE _plsw_storage;
14	 *
15	 * Macro form (PL/I-flavored; preferred surface):
16	 *   ?GETMAIN  SET(P)  LENGTH(N)  RC(ret);
17	 *     -- expands to: P = _PLSW_GETMAIN(N);
18	 *                    IF (P = 0) THEN ret = 4; ELSE ret = 0;
19	 *     -- ret is 0 on success, 4 on out-of-memory.
20	 *
21	 *   ?FREEMAIN ADDR(P) LENGTH(N) RC(ret);
22	 *     -- expands to: ret = _PLSW_FREEMAIN(P, N);
23	 *     -- ret passes through the procedure's return:
24	 *          0 = success
25	 *          1 = double-free / invalid pointer
26	 *          2 = size mismatch (LENGTH doesn't match recorded size)
27	 *
28	 * Clause naming follows MVS convention:
29	 *   SET(lvalue)   -- GETMAIN: receive-pointer (written)
30	 *   ADDR(lvalue)  -- FREEMAIN: source-pointer (read)
31	 *   LENGTH(expr)  -- block size in bytes
32	 *   RC(lvalue)    -- return code (written)
33	 *
34	 * Invocation syntax is PL/X: space-separated parenthetical
35	 * clauses, no outer parens, statement-terminated. Clauses may
36	 * appear in any order.
37	 *
38	 * All clauses are REQUIRED in v1. Future saga can make RC
39	 * optional once PL/SW's macro system supports %IF DEFINED
40	 * inside templates.
41	 *
42	 * Procedure form (lower-level surface; same effect):
43	 *   P  = _PLSW_GETMAIN(N);            P=0 on OOM
44	 *   RC = _PLSW_FREEMAIN(P, N);        same RC values as above
45	 *
