78	/* --- Heap region + free-list head --- */
79	DCL _PLSW_HEAP_BUF(PLSW_HEAP_SIZE) BYTE;
80	DCL _PLSW_FREE_HEAD INT INIT(0);
81	DCL _PLSW_INIT_DONE INT INIT(0);
82	
83	/* Lazy init: first call to _PLSW_GETMAIN sets up one giant free
84	 * block covering the entire heap region. */
85	_PLSW_INIT: PROC;
86	    _PLSW_FREE_HEAD = ADDR(_PLSW_HEAP_BUF);
87	    _PLSW_BP = _PLSW_FREE_HEAD;
88	    _PLSW_BP->_PLSW_BLOCK_SIZE = PLSW_HEAP_SIZE;
89	    _PLSW_BP->_PLSW_BLOCK_NEXT = 0;
90	    _PLSW_INIT_DONE = 1;
91	END;
