93	/* _PLSW_GETMAIN(SIZE) -- allocate SIZE user bytes.
94	 * Returns address of the user block (after the 6-byte header),
95	 * or 0 on out-of-memory. First-fit; splits the chosen block when
96	 * the remainder leaves room for another header + min user byte. */
97	_PLSW_GETMAIN: PROC(SIZE INT) RETURNS(INT);
98	    DCL NEEDED INT;
99	    DCL PREV INT;
100	    DCL CURR INT;
101	    DCL CURR_SIZE INT;
102	    DCL CURR_NEXT INT;
103	    DCL NEW_FREE INT;
104	
105	    IF (_PLSW_INIT_DONE = 0) THEN
106	        CALL _PLSW_INIT();
107	
108	    NEEDED = SIZE + 6;
109	
110	    PREV = 0;
111	    CURR = _PLSW_FREE_HEAD;
112	    DO WHILE (CURR != 0);
113	        _PLSW_BP = CURR;
114	        CURR_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
115	        CURR_NEXT = _PLSW_BP->_PLSW_BLOCK_NEXT;
116	        IF (CURR_SIZE >= NEEDED) THEN DO;
117	            IF (CURR_SIZE >= NEEDED + 7) THEN DO;
118	                /* Split: allocated block stays at CURR; free
119	                 * remainder starts at CURR + NEEDED */
120	                NEW_FREE = CURR + NEEDED;
121	                _PLSW_BP = NEW_FREE;
122	                _PLSW_BP->_PLSW_BLOCK_SIZE = CURR_SIZE - NEEDED;
123	                _PLSW_BP->_PLSW_BLOCK_NEXT = CURR_NEXT;
124	                _PLSW_BP = CURR;
125	                _PLSW_BP->_PLSW_BLOCK_SIZE = NEEDED;
126	                _PLSW_BP->_PLSW_BLOCK_NEXT = _PLSW_ALLOC_MAGIC;
127	                IF (PREV = 0) THEN
128	                    _PLSW_FREE_HEAD = NEW_FREE;
129	                ELSE DO;
130	                    _PLSW_BP = PREV;
131	                    _PLSW_BP->_PLSW_BLOCK_NEXT = NEW_FREE;
132	                END;
133	            END;
134	            ELSE DO;
135	                /* Use whole block (remainder too small to be useful) */
136	                _PLSW_BP = CURR;
137	                _PLSW_BP->_PLSW_BLOCK_NEXT = _PLSW_ALLOC_MAGIC;
138	                IF (PREV = 0) THEN
139	                    _PLSW_FREE_HEAD = CURR_NEXT;
140	                ELSE DO;
141	                    _PLSW_BP = PREV;
142	                    _PLSW_BP->_PLSW_BLOCK_NEXT = CURR_NEXT;
143	                END;
144	            END;
145	            RETURN(CURR + 6);
146	        END;
147	        PREV = CURR;
148	        CURR = CURR_NEXT;
149	    END;
150	    RETURN(0);
151	END;
152	
153	/* _PLSW_FREEMAIN(USERADDR, LEN) -- free a previously-allocated
154	 * block.  Returns:
155	 *   0 = success
156	 *   1 = block not allocated (double-free, invalid pointer, or
157	 *       corrupted header sentinel)
158	 *   2 = size mismatch (LEN doesn't match allocated size) */
159	_PLSW_FREEMAIN: PROC(USERADDR INT, LEN INT) RETURNS(INT);
160	    DCL BLOCK INT;
161	    DCL EXPECTED INT;
162	    DCL PREV INT;
163	    DCL CURR INT;
164	    DCL BLK_SIZE INT;
165	    DCL NEXT_AFTER INT;
166	    DCL NEXT_SIZE INT;
167	
168	    BLOCK = USERADDR - 6;
169	    EXPECTED = LEN + 6;
170	
171	    _PLSW_BP = BLOCK;
172	    /* Double-free / invalid-pointer check */
173	    IF (_PLSW_BP->_PLSW_BLOCK_NEXT != _PLSW_ALLOC_MAGIC) THEN
174	        RETURN(1);
175	    /* Size mismatch */
176	    IF (_PLSW_BP->_PLSW_BLOCK_SIZE != EXPECTED) THEN
177	        RETURN(2);
178	
179	    /* Sorted insert: walk free list to find PREV (last block with
180	     * addr < BLOCK) and CURR (first block with addr >= BLOCK). */
181	    PREV = 0;
182	    CURR = _PLSW_FREE_HEAD;
183	    DO WHILE (CURR != 0 AND CURR < BLOCK);
184	        PREV = CURR;
185	        _PLSW_BP = CURR;
186	        CURR = _PLSW_BP->_PLSW_BLOCK_NEXT;
187	    END;
188	
189	    /* Link block in: block.next = curr; prev.next = block (or head) */
190	    _PLSW_BP = BLOCK;
191	    _PLSW_BP->_PLSW_BLOCK_NEXT = CURR;
192	    IF (PREV = 0) THEN
193	        _PLSW_FREE_HEAD = BLOCK;
194	    ELSE DO;
195	        _PLSW_BP = PREV;
196	        _PLSW_BP->_PLSW_BLOCK_NEXT = BLOCK;
197	    END;
198	
199	    /* Forward coalesce: if BLOCK end touches CURR, merge */
200	    _PLSW_BP = BLOCK;
201	    BLK_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
202	    IF (CURR != 0) THEN DO;
203	        IF (BLOCK + BLK_SIZE = CURR) THEN DO;
204	            _PLSW_BP = CURR;
205	            NEXT_AFTER = _PLSW_BP->_PLSW_BLOCK_NEXT;
206	            NEXT_SIZE = _PLSW_BP->_PLSW_BLOCK_SIZE;
207	            _PLSW_BP = BLOCK;
208	            _PLSW_BP->_PLSW_BLOCK_SIZE = BLK_SIZE + NEXT_SIZE;
209	            _PLSW_BP->_PLSW_BLOCK_NEXT = NEXT_AFTER;
210	        END;
211	    END;
212	
213	    RETURN(0);
214	END;
215	
216	%ENDIF;
